type MessageCatalog = (typeof messages)[Language];
export type Messages = Omit<MessageCatalog, 'instruments'> & { instruments: Omit<MessageCatalog['instruments'], 'dimensions'> & { dimensions: Record<string,string> } };

export function isLanguage(value: unknown): value is Language {
  return typeof value === 'string' && languages.includes(value as Language);
}
